codeBackup.css_template:
#{{ID}} .rep-top-bar {
    position: absolute;
    top: 0;
    left: 0;
    width: {{V_WIDTH}}px;
    box-sizing: border-box;
    min-height: auto;
    max-height: {{V_HEIGHT}}px;
    overflow: hidden;
    background: {{PRIMARY_BG}};
    color: {{TITLE_COLOR}};
    display: block;
    padding: 5px 30px;
    font-family: '{{FONT_FAMILY}}', 'Roboto Condensed', sans-serif;
    box-shadow: {{BOX_SHADOW}};
    opacity: 0;
    transform-origin: left center;
    transform: {{ANIMATION_IN_TRANSFORM}};
    transition: all {{ANIMATION_DURATION}}s {{ANIMATION_EASE}};
}
#{{ID}} .rep-title {
    font-size: {{TITLE_SIZE}}px;
    font-weight: {{TITLE_WEIGHT}};
    text-transform: {{TITLE_TRANSFORM}};
    white-space: pre-line;
    z-index: 2;
    letter-spacing: -0.5px;
    color: {{TITLE_COLOR}};
}
#{{ID}} .rep-title div, #{{ID}} .rep-title p { margin: 0; padding: 0; }
#{{ID}} .rep-side-graphic {
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: {{V_WIDTH}}px;
    background: url('{{SIDE_IMAGE}}') center/cover;
    opacity: 0.8;
}
#{{ID}} .rep-side-graphic::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(to right, {{PRIMARY_BG}} 0%, transparent 100%);
}

codeBackup.js_template:
(() => {
    const root = document.getElementById("{{ID}}");
    const container = root.querySelector(".rep-top-bar");
    const side = root.querySelector(".rep-side-graphic");
    const textIn = {{{TEXT_ANIM_JSON}}};
    const textOut = {{{TEXT_ANIM_OUT_JSON}}};
    const has = c => c && c.type && c.type !== 'none';
    CGMotion.mount(root, {
        container,
        animIn: {{{ANIMATION_IN_JSON}}},
        animOut: {{{ANIMATION_OUT_JSON}}},
        // Domyślne efekty tekstu (clip-up / clip-down), jeśli operator nie wybrał własnych
        text: has(textIn) ? textIn : { type: 'clip-up', duration: 0.45, delay: 0.1 },
        textSync: {{{TEXT_ANIM_SYNC}}},
        textOut: has(textOut) ? textOut : { type: 'clip-down', duration: 0.3 },
        textOutSync: {{{TEXT_ANIM_OUT_SYNC}}},
        loop: {{{LOOP_JSON}}},
        onShow: (tl) => { if (side) tl.add(CGMotion.build([{ target: side, type: 'fade', duration: 0.35 }]), 0.15); },
    });
})();

