/* SceneModel v1 — wygenerowane ze sceny, nie edytuj ręcznie */
#{{ID}} .cg-scene { position: relative; width: 1650px; height: 150px; pointer-events: none; transform: scale(var(--cg-sx, 1), var(--cg-sy, 1)); transform-origin: top left; }
#{{ID}} .cg-l, #{{ID}} .cg-i { box-sizing: border-box; }
#{{ID}} .cg-l { position: absolute; }
#{{ID}} .cg-i { position: absolute; inset: 0; }
#{{ID}} .cg-l1 { left: 0px; top: 0px; width: 1650px; height: 150px; z-index: 1; }
#{{ID}} .cg-i1 { background: rgb(0, 71, 171); }
#{{ID}} .cg-l2 { left: 29.8px; top: 10px; width: 441px; height: 42px; z-index: 2; }
#{{ID}} .cg-i2 { display: flex; justify-content: flex-start; align-items: center; font-family: 'Inter', sans-serif; font-size: 30px; font-weight: 700; color: rgb(255, 255, 255); text-transform: uppercase; text-align: left; letter-spacing: -0.5px; line-height: 1.4; white-space: nowrap; }
